pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Ensure _owner is not the zero address to avoid revert from require
        vm.assume(_owner != address(0));
        // Record the initial owner
        address initialOwner = c.owner();
        // Call setOwner with a different address
        c.setOwner(_owner);
        // The owner should still be the initial owner (since the bug removed the assignment)
        assertTrue(c.owner() == initialOwner);
    }
}

