pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address _owner) public {
        vm.assume(caller == c.owner());
        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, _owner));
        assertTrue(success);
        if (data.length > 0) {
            bool returnValue = abi.decode(data, (bool));
            assertTrue(returnValue);
        }
    }
}

